@props(['title','appointments','empty'])
<section class="hn-panel"><div class="hn-panel-header"><div><h2 class="hn-panel-title">{{ $title }}</h2><p class="hn-panel-subtitle">{{ number_format($appointments->count()) }} موعد</p></div><a href="{{ url('appointments') }}" class="tx-13">عرض الكل</a></div>@if($appointments->isEmpty())<x-ui.empty :title="$empty" icon="fe-calendar" />@else<div class="hn-table-responsive"><table class="hn-table"><thead><tr><th>المريض</th><th>التاريخ</th><th>الوقت</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>@foreach($appointments as $appointment)@php($patientFile=optional($appointment->patient)->gnr_m_patients)<tr><td>@if($patientFile)<a href="{{ route('visits.show',$patientFile->id) }}"><strong>{{ optional($appointment->patient)->name }}</strong></a>@else{{ optional($appointment->patient)->name ?? 'غير محدد' }}@endif</td><td>{{ $appointment->appointment_date ? \Carbon\Carbon::parse($appointment->appointment_date)->format('Y/m/d') : '—' }}</td><td>{{ $appointment->time ? \Carbon\Carbon::parse($appointment->time)->format('h:i A') : '—' }}</td><td><span class="hn-badge {{ (int)$appointment->status===1?'hn-badge-success':((int)$appointment->status===2?'hn-badge-danger':'hn-badge-pending') }}">{{ (int)$appointment->status===1?'مؤكد':((int)$appointment->status===2?'ملغي':'قيد الانتظار') }}</span></td><td>@if((int)$appointment->status===1)<a class="hn-btn hn-btn-primary hn-btn-sm" href="{{ route('consultations.start',$appointment) }}"><i class="fe fe-clipboard"></i> بدء المعاينة</a>@else<span class="text-muted">يلزم التأكيد</span>@endif</td></tr>@endforeach</tbody></table></div>@endif</section>
